import{_ as a,H as p,f as t,i as l}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"结束语 | 尽最大的努力，做最好的自己","description":"","frontmatter":{},"headers":[{"level":2,"title":"做一个长期坚持做事的人","slug":"做一个长期坚持做事的人","link":"#做一个长期坚持做事的人","children":[]},{"level":2,"title":"做一个靠谱的人","slug":"做一个靠谱的人","link":"#做一个靠谱的人","children":[]},{"level":2,"title":"做一个持续学习的人","slug":"做一个持续学习的人","link":"#做一个持续学习的人","children":[]},{"level":2,"title":"做一个乐观的人","slug":"做一个乐观的人","link":"#做一个乐观的人","children":[]},{"level":2,"title":"结语","slug":"结语","link":"#结语","children":[]}],"relativePath":"深入拆解消息队列47讲/结束语｜尽最大的努力，做最好的自己.md","filePath":"深入拆解消息队列47讲/结束语｜尽最大的努力，做最好的自己.md","lastUpdated":1795530488000}'),i={name:"深入拆解消息队列47讲/结束语｜尽最大的努力，做最好的自己.md"};function r(n,e,o,s,h,_){return p(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="结束语-尽最大的努力-做最好的自己" tabindex="-1">结束语 | 尽最大的努力，做最好的自己 <a class="header-anchor" href="#结束语-尽最大的努力-做最好的自己" aria-label="Permalink to &quot;结束语 | 尽最大的努力，做最好的自己&quot;">​</a></h1><p>你好，我是文强。</p><p>今天，是我们这个专栏的最后一节课了。我想和你聊聊我自己关于技术生涯的一些想法，权当总结和共勉吧。</p><p>内容可能会有点鸡汤，道理可能你也都懂，但同行的路上，我觉得还是要给彼此一些鼓励和信心，让我们都能在技术这条路上坚定地走下去。</p><p>近几年，关于程序员的职业生涯，35 岁是个门槛的说法，可以说是研发人员焦虑的一大来源。伴随着疫情、大环境等一些因素的影响，互联网裁员潮此起彼伏。国内外顶尖的互联网公司都在收缩，就业环境越来越恶劣。</p><p>我第一份工作的 Leader 离职时，说过这么一句话：“我现在做的事情你们都能做，那我的竞争力是什么？”那时候我刚毕业两年，似懂非懂，但后来这句话一直警醒着我。</p><p>今年更是经常思考：毕业多年，我自己的核心竞争力是什么？我和刚毕业的那些年轻同学相比，我的优势是什么？</p><p>乐观来讲，我觉得自己没有浪费什么时间。从毕业到现在，一直在学习各种技术，看各种书，也有一个明确的目标，就是在行业内慢慢建立自己的影响力，成为技术大牛。从 Web、App那套讲究高并发 To C 的技术栈，到基础组件如容器、K8s、搜索、大数据等我都有涉猎，到最后深入消息队列这个领域。</p><p>悲观来讲，我觉得现在的我和我们 Team 的成员比，好像我做的他们也都能做，我会的只要他们肯学他们也可以会，甚至可以做得更好。而且他们比我有更多的时间学习和深入思考，对公司来讲单位时间成本也更低。</p><p>工作多年后，一个很残酷的事实是，慢慢认识到自己就是个普通人。那作为普通人，应该怎样延长自己的职业生涯呢？</p><p>我的答案是：要“卷”，要聪明地“卷”，通过有意义、有规划、有目标地“卷”来达到目的。</p><p>具体来讲，我把“卷”拆解成四件事儿。</p><ol><li><p>做一个长期坚持做事的人</p></li><li><p>做一个靠谱的人</p></li><li><p>做一个持续学习的人</p></li><li><p>做一个乐观的人</p></li></ol><h2 id="做一个长期坚持做事的人" tabindex="-1">做一个长期坚持做事的人 <a class="header-anchor" href="#做一个长期坚持做事的人" aria-label="Permalink to &quot;做一个长期坚持做事的人&quot;">​</a></h2><p>我自己是比较相信，在计算机工程方面，拼的就是“体力活”。</p><p>只要肯花时间、花精力，长期坚持去学习、去行动，在技术能力发展方面一定会有一个好的结果，至少可以带给我们一份稳定的工作和收入。换句话说，长期坚持做事一定会保证你的下限。</p><p>而如果要提高上限，我认为还是体力活，但得加一点小要求，应该是聪明一点、变通一点的体力活，要加上思考能力。</p><p>思考自己还缺什么，市场或者团队还缺什么，哪个事情可以给你带来更高的收益。然后及时调整学习和发展的方向，调整做事的方式。力求事半功倍，切忌埋头苦干。</p><h2 id="做一个靠谱的人" tabindex="-1">做一个靠谱的人 <a class="header-anchor" href="#做一个靠谱的人" aria-label="Permalink to &quot;做一个靠谱的人&quot;">​</a></h2><p>在成为技术大牛的路上，我们会遇到很多分叉路口，比如现在技术领域和方向这么多，要学习哪些技术呢？先走广度，还是先走深度？最近 AI 那么火，要不要早点去学习？</p><p>答案很多，每个方向也都有成功的先例，但我们可以从中找到一个共性。如果周围人给你的标签是“靠谱”，那么你就已经在通往成功的路上了。</p><p>靠谱说明大家信任你，找你帮忙解决的问题你都能应对，或者你可以协调解决，尝试一起解决。在这个过程中，你会去理解同事或者客户需要什么，下意识去完善自己的能力，比如技术能力、沟通能力、团队影响力等等。</p><h2 id="做一个持续学习的人" tabindex="-1">做一个持续学习的人 <a class="header-anchor" href="#做一个持续学习的人" aria-label="Permalink to &quot;做一个持续学习的人&quot;">​</a></h2><p>技术迭代这么快，如果吃老本，天天抱着 Java Spring 的一亩三分地，做 CRUD 的事情，肯定会失去竞争力。</p><p>如果我们具备持续学习的能力，就可以做到别人会的我也会。而我们基于之前的经验，掌握新技能的速度会更快。即使更换赛道，持续学习也可以帮助我们快速融入新环境，在新的赛道也成为一个优秀的人。</p><p>工作多年，我发现身边那些技术大牛都是拥有持续学习能力的人。他们学习的东西，不一定是工程技术，也不一定是最前沿的东西，但一定是他们需要的。</p><p>还有同事之间相比，如果技术能力上有一些差距，通过持续学习是可以赶上的。</p><h2 id="做一个乐观的人" tabindex="-1">做一个乐观的人 <a class="header-anchor" href="#做一个乐观的人" aria-label="Permalink to &quot;做一个乐观的人&quot;">​</a></h2><p>很多情况下，可能我们付出了很多努力，但结果依旧不尽人意。这才是生活的常态。</p><p>在广东、香港这一块，风水是一个需求很旺盛的行业。之前不太理解，写个代码看什么风水，后来经历了一些事情，才体会到寄希望于玄学是怎样的一种心态。工作中，除了坚持、靠谱、学习，还需要一点运气。有句话不是说嘛，选择比努力更重要。</p><p>但这只能算一个 buff 叠加，我觉得还是要对自己的人生保持掌控感。换句话说，人生不能摆烂，听天命之前要尽人事。</p><p>所以遇到什么事情，我都是先努力了再说，保持乐观的心态，结果往往很好。</p><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>我很理解，大环境不好，生活总有压力。时代的一粒灰，落在个人头上，就是一座山。困难面前，要学会尽最大的努力，做最好的自己。</p><p>最后我还想分享一个我的减压方法给你，那就是健身。</p><p>健身对程序员来讲，是一件 ROI 很高的事情。它能让我们体态更佳，身体更健康。更重要的是，这是一件完全可控且坚持就能带来好结果的事情，在我们面对很多不确定时还能带来强大的力量，培养正面情绪。科学上来说，运动过程中分泌的多巴胺会冲淡很多负面情绪。</p><p>我跑步时经常看 B 站的各种正能量短视频和番剧。比如余华、罗翔，或者各种不知名的热血鸡汤短视频。我觉得这是一个很好的充电方式，看到大家都在努力，也会激励到自己。</p><p>分享一个我最喜欢的短视频，功夫熊猫中的经典台词这样说：你患得患失，太在意从前，又太担心将来。昨天是段历史，明天是个谜团。而今天是天赐的礼物，像珍惜礼物那样珍惜今天。</p><p>与你共勉！我们江湖再见。</p><p>这里是一份结课问卷，如果你在学习的过程中遇到了问题，对课程有建议或意见，欢迎指出，我们会根据你的反馈持续迭代课程。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/1.png" alt=""></a></p>',41)])])}const u=a(i,[["render",r]]);export{c as __pageData,u as default};
